const burger=document.querySelector(".burger"),nav=document.querySelector(".nav");burger&&nav&&burger.addEventListener("click",()=>{const e=nav.classList.toggle("nav--open");burger.setAttribute("aria-expanded",String(e)),burger.setAttribute("aria-label",e?"Закрыть меню":"Открыть меню"),burger.textContent=e?"✕":"☰"});const subscribeForm=document.querySelector(".subscribe");subscribeForm&&subscribeForm.addEventListener("submit",e=>{e.preventDefault();const t=subscribeForm.querySelector(".subscribe__input").value.trim();subscribeForm.querySelector(".subscribe__result").textContent=`Готово! Адрес ${t} добавлен в список (учебная форма, письма не придут).`,subscribeForm.reset()});const feedbackForm=document.querySelector(".form");feedbackForm&&feedbackForm.addEventListener("submit",e=>{e.preventDefault();const t=feedbackForm.querySelector("#user-name").value.trim();feedbackForm.querySelector(".form__result").textContent=`Спасибо, ${t}! Сообщение принято. Сайт учебный, поэтому данные никуда не отправляются.`,feedbackForm.reset()});const demoButton=document.querySelector("#demo-btn");demoButton&&demoButton.addEventListener("click",()=>{const e=document.querySelector("#demo-name").value.trim()||"гость",t=(new Date).getHours(),r=t<12?"Доброе утро":t<18?"Добрый день":"Добрый вечер";document.querySelector("#demo-output").textContent=`${r}, ${e}! Сейчас ${t} ч.`});